const body = $input.first().json.body || $input.first().json;

return {
  json: {
    hazardId: body.hazardId,
    resolutionStatus: 'RESOLUTION_SUBMITTED',
    assignedTeam: body.assignedTeam || 'Maintenance Squad',
    remarks: body.resolutionRemarks || 'Repairs completed',
    hasProofPhoto: Boolean(body.resolutionEvidenceUrl),
    verifiedByAuthority: true,
    processedAt: new Date().toISOString()
  }
};

const item = $input.first().json;

return {
  json: {
    success: true,
    workflow: 'RoadSense — Resolution Evidence Follow-up',
    hazardId: item.hazardId,
    status: item.hasProofPhoto ? 'CONFIRMED_RESOLVED' : 'RESOLUTION_AWAITING_PROOF',
    taskCreated: 'Notified citizen reporting community of patch completion',
    timestamp: new Date().toISOString()
  }
};
